 it('emits focus rules only on attached scopes',()=>{const dir=mkdtempSync(join(tmpdir(),'pipe-style-focus-semantic-')); generate(toIR(parse('app Styled\nstyle named Form focus is ringed\ncomponent Copy uses style Form { text "Text" }\npage Home { use Copy }')),dir); const html=readFileSync(join(dir,'index.html'),'utf8'); expect(html).toContain('[data-pipe-style="Form"] input:focus-visible,[data-pipe-style="Form"] button:focus-visible{outline:var(--bmec-focus-width) solid var(--bmec-color-focus-ring-strong);outline-offset:var(--bmec-focus-offset)}');});
 it('emits surface rules only on attached scopes',()=>{const dir=mkdtempSync(join(tmpdir(),'pipe-style-surface-semantic-')); generate(toIR(parse('app Styled\nstyle named Card surface is elevated\ncomponent Copy uses style Card { text "Text" }\npage Home { use Copy }')),dir); const html=readFileSync(join(dir,'index.html'),'utf8'); expect(html).toContain('[data-pipe-style="Card"] input,[data-pipe-style="Card"] button{box-shadow:0 2px 8px #0003}');});
 it('emits text rules only on attached scopes',()=>{const dir=mkdtempSync(join(tmpdir(),'pipe-style-text-semantic-')); generate(toIR(parse('app Styled\nstyle named Copy text is muted\ncomponent CopyComponent uses style Copy { text "Text" }\npage Home { use CopyComponent }')),dir); const html=readFileSync(join(dir,'index.html'),'utf8'); expect(html).toContain('[data-pipe-style="Copy"]{color:#94a3b8}');});
